-- ============================================
--  Bank Database – MySQL  (one INSERT per row)
--  Table: client  |  Rows: 3000
-- ============================================

CREATE DATABASE IF NOT EXISTS bank
  CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;

USE bank;

DROP TABLE IF EXISTS client;

CREATE TABLE client (
  id            INT            NOT NULL AUTO_INCREMENT,
  name          VARCHAR(100)   NOT NULL,
  national_id   CHAR(14)       NOT NULL,
  phone         VARCHAR(15)    NOT NULL,
  email         VARCHAR(150)   NOT NULL,
  gender        ENUM('Male','Female') NOT NULL,
  birth_date    DATE           NOT NULL,
  city          ENUM('Cairo','Assiut','Luxor','Alexandria') NOT NULL,
  address       VARCHAR(255)   NOT NULL,
  account_type  ENUM('Savings','Current','Fixed Deposit','Business') NOT NULL,
  balance       DECIMAL(12,2)  NOT NULL DEFAULT 0.00,
  created_at    DATE           NOT NULL,
  PRIMARY KEY (id),
  UNIQUE KEY uq_national_id (national_id),
  INDEX idx_city (city),
  INDEX idx_account_type (account_type)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

